2:['M=2+3+5=10\\,\\mathrm{kg}','\\bar{x}=\\frac{2(1)+3(4)+5(2)}{10}','\\bar{x}=\\frac{2+12+10}{10}=\\frac{24}{10}','\\boxed{\\bar{x}=2.4\\,\\mathrm{m}}','\\bar{y}=\\frac{2(2)+3(1)+5(5)}{10}=\\frac{32}{10}','\\boxed{(\\bar{x},\\bar{y})=(2.4,3.2)\\,\\mathrm{m}}'],
3:['A_1=4(4)=16\\,\\mathrm{cm}^2,\\qquad A_2=\\frac{4(3)}{2}=6\\,\\mathrm{cm}^2','\\bar{y}_1=2\\,\\mathrm{cm},\\qquad \\bar{y}_2=4+\\frac{3}{3}=5\\,\\mathrm{cm}','\\bar{y}=\\frac{16(2)+6(5)}{16+6}=\\frac{62}{22}','\\boxed{\\bar{y}=\\frac{31}{11}\\,\\mathrm{cm}\\approx2.82\\,\\mathrm{cm}}'],
