let state={route:'home',labId:null,step:0,reveal:0,guide:false,params:{}};
const main=document.getElementById('main');
const fmt=n=>Number(n).toFixed(2).replace(/\.00$/,'');
function route(name,id){state.route=name;state.labId=id||null;state.step=0;state.reveal=0;state.guide=false;render();window.scrollTo({top:0,left:0,behavior:'instant'})}
function home(){return `<div class="view home"><section class="hero"><div><p class="eyebrow">CÁLCULO II · EXPERIENCIA INTERACTIVA</p><h1>CENTRO<em>Laboratorio</em></h1><p class="hero-copy">Seis problemas, una idea esencial: comprender dónde se concentra una figura, una masa o una fuerza. Explora, calcula y explica con el método de George Pólya.</p><div class="hero-actions"><button class="primary" data-lab="1">Comenzar laboratorio 01 →</button><button class="secondary" data-route="theory">Revisar fundamentos</button></div></div><div class="hero-visual" aria-label="Representación conceptual de un centro de masa"><div class="axis-line"></div><div class="orbit o1"><i class="orbit-dot"></i></div><div class="orbit o2"><i class="orbit-dot"></i></div><div class="orbit o3"><i class="orbit-dot"></i></div><div class="mass-core"><span>CM</span></div><p class="hero-meta">Carlos Eduardo Díaz García<br>Cálculo II · 2026</p></div></section><section><div class="section-head"><div><p class="eyebrow">TICKET DE SALIDA</p><h2>Seis niveles.<br>Seis pequeñas clases.</h2></div><p>De la simetría directa a la integración en un campo gravitatorio variable. Cada laboratorio integra visualización, desarrollo y verificación.</p></div><div class="lab-grid">${labs.map(card).join('')}</div></section></div>`}
function card(l){return `<article class="lab-card" data-lab="${l.id}" style="--accent:${l.accent}" tabindex="0"><span class="pisa">NIVEL ${l.level} PISA</span><h3>${l.title}</h3><p>${l.short}</p><span class="card-link">Abrir laboratorio →</span><b class="card-num">0${l.id}</b></article>`}
function theory(){return `<div class="view theory-view"><section class="theory-hero"><p class="eyebrow">FUNDAMENTOS TEÓRICOS</p><h1>Tres centros.<br>Una distinción crucial.</h1><p class="lead">La posición central cambia según lo que ponderamos: geometría, masa o fuerza gravitatoria. En un cuerpo homogéneo dentro de un campo uniforme, los tres pueden coincidir; fuera de esas condiciones, no necesariamente.</p></section><section class="concept-row"><article class="concept"><strong>Centroide</strong><p>Centro geométrico de una línea, área o volumen. No requiere masa cuando la figura se estudia puramente como geometría.</p></article><article class="concept"><strong>Centro de masa</strong><p>Punto medio de la distribución de masa. Depende de cómo se reparte la materia y no del campo gravitatorio.</p></article><article class="concept"><strong>Centro de gravedad</strong><p>Punto de aplicación de la resultante gravitatoria. Coincide con el CM cuando el campo es uniforme.</p></article></section><section class="formula-band"><div><p class="eyebrow">PARTÍCULAS</p><div class="formula">x̄ = Σmᵢxᵢ / Σmᵢ<br>ȳ = Σmᵢyᵢ / Σmᵢ</div></div><div><p class="eyebrow">ÁREAS COMPUESTAS</p><div class="formula">x̄ = ΣAᵢxᵢ / ΣAᵢ<br>ȳ = ΣAᵢyᵢ / ΣAᵢ</div></div></section><section><div class="section-head"><div><p class="eyebrow">MÉTODO DE GEORGE PÓLYA</p><h2>Una estructura para razonar.</h2></div></div><div class="polya-line">${['Comprender el problema|Identificar datos, incógnitas, condiciones y supuestos.','Configurar un plan|Elegir una estrategia y justificar por qué corresponde.','Ejecutar el plan|Desarrollar operaciones con precisión, notación y unidades.','Mirar hacia atrás|Verificar coherencia geométrica, numérica y física.'].map((x,i)=>{const [a,b]=x.split('|');return `<article class="polya-item"><span>0${i+1}</span><h3>${a}</h3><p>${b}</p></article>`}).join('')}</div></section><div class="hero-actions" style="margin-top:60px"><button class="primary" data-lab="1">Ir a los laboratorios →</button><button class="secondary" data-route="home">Volver al inicio</button></div></div>`}
const tex=t=>`<div class="math-line" data-tex="${encodeURIComponent(t)}"></div>`;
function resultVisible(l){return state.step===3||(state.step===2&&state.reveal>=mathReveals[l.id].length)}
function originalStatement(l){return `<section class="original-statement"><span>ENUNCIADO ORIGINAL · TICKET DE SALIDA</span><p>${originals[l.id].replace(/ • Consigna:/,'</p><p class="consigna"><b>Consigna:</b>').replace(/ − /g,'<br>− ')}</p></section>`}
function stageMath(l){if(state.step===1)return `<div class="solution-label">MODELO MATEMÁTICO</div><div class="math-block composed">${planMath[l.id].map(tex).join('')}</div>`;if(state.step===2){const all=mathReveals[l.id],shown=all.slice(0,state.reveal);return `<div class="solution-label">DESARROLLO · PASO ${Math.min(state.reveal+1,all.length)} DE ${all.length}</div><div class="math-block composed reveal-sequence">${shown.length?shown.map((x,i)=>`<div class="revealed-equation">${tex(x)}</div>`).join(''):'<p class="reveal-prompt">Avanza para sustituir los datos y revelar la primera operación.</p>'}</div><div class="substep-hint">${state.reveal<all.length?'→ Siguiente: revelar una operación':'✓ Desarrollo completo; el resultado ya puede interpretarse.'}</div>`}if(state.step===3)return `<div class="solution-label">RESULTADO OBTENIDO</div><div class="math-block composed final-result">${tex(resultMath[l.id])}</div>`;return ''}
function labView(l){const s=l.steps[state.step],exploring=!!state.params[l.id],revealed=resultVisible(l),nextLabel=state.step===2&&state.reveal<mathReveals[l.id].length?'Revelar siguiente →':'Siguiente etapa →';return `<div class="view lab-view lab-${l.id} ${exploring?'is-exploring':''} ${revealed?'result-revealed':'result-hidden'}" style="--accent:${l.accent}"><div class="lab-shell"><aside class="lab-rail"><div class="rail-num">0${l.id}</div><div class="rail-level">NIVEL ${l.level} PISA</div><div class="rail-dots">${l.steps.map((_,i)=>`<button class="rail-dot ${i===state.step?'active':''}" data-step="${i}" aria-label="Ir a etapa ${i+1}">${i+1}</button>`).join('')}</div><button class="tool-btn" data-route="home" aria-label="Inicio">⌂</button></aside><section class="lab-stage"><header class="lab-head"><div class="lab-title"><p>LABORATORIO 0${l.id} · <span class="header-result">${revealed?l.official:'RESULTADO POR DESCUBRIR'}</span></p><h1>${l.title}</h1></div><div class="lab-head-actions"><button class="tool-btn" id="resetBtn">↻ <span>Reiniciar ejercicio</span></button><button class="tool-btn" id="guideBtn">☰ <span>Guía</span></button></div></header><div class="step-area"><article class="lesson-copy"><div class="step-marker"><span>0${state.step+1}</span><p>${['COMPRENDER EL PROBLEMA','CONFIGURAR UN PLAN','EJECUTAR EL PLAN','MIRAR HACIA ATRÁS'][state.step]}</p></div><h2>${s.title}</h2>${state.step===0?originalStatement(l):''}<p class="narrative">${s.text}</p>${s.data?`<div class="data-list">${s.data.map(d=>`<div class="data-row"><span>${d[0]}</span><strong>${d[1]}</strong></div>`).join('')}</div>`:''}${stageMath(l)}${s.checks?`<ul class="check-list">${s.checks.map(c=>`<li>${c}</li>`).join('')}</ul>`:''}${experiment(l)}</article><figure class="visual-panel"><div class="viz-title"><span>MODELO VISUAL</span><strong>${l.short}</strong></div><div class="viz-wrap">${visual(l)}</div><figcaption class="viz-caption"><div class="legend">${legend(l)}</div><span class="official">${exploring?'MODO EXPLORACIÓN':'ESCENARIO OFICIAL'}</span></figcaption></figure></div><footer class="step-nav"><button class="nav-btn prev" ${state.step===0&&state.reveal===0?'disabled':''}>← ${state.step===2&&state.reveal>0?'Ocultar operación':'Etapa anterior'}</button><div class="progress">${l.steps.map((_,i)=>`<span class="${i<=state.step?'done':''}"></span>`).join('')}</div><button class="nav-btn next" ${state.step===3?'disabled':''}>${nextLabel}</button></footer></section></div>${guide(l)}</div>`}
function guide(l){return `<aside class="guide ${state.guide?'open':''}" id="guidePanel"><button class="guide-close" id="guideClose">×</button><p class="eyebrow">GUÍA DEL EXPOSITOR</p><h2>Una ruta breve para explicar</h2><h3>Secuencia de revelación</h3><p>Lee primero el enunciado. Presenta después el modelo general. En la etapa 03, avanza una operación cada vez y deja una pausa para explicarla antes de revelar la siguiente.</p><h3>Cómo introducir</h3><p>${l.guide.intro}</p><h3>Qué señalar</h3><p>${l.guide.point}</p><h3>Cómo justificar</h3><p>${l.guide.justify}</p><h3>Error a evitar</h3><p>${l.guide.errors}</p><h3>Conclusión natural</h3><p>${l.guide.close}</p></aside>`}
function experiment(l){const p=state.params[l.id]||{},configs={1:['L','Longitud',p.L??1.8,.8,3,.1,'m'],2:['m3','Masa m₃',p.m3??5,1,10,1,'kg'],3:['h','Altura triangular',p.h??3,1,5,.5,'cm'],4:['load','Masa de maquinaria',p.load??2000,0,4000,250,'kg'],5:['n','Exponente n',p.n??2,0,5,1,''],6:['k','Gradiente k',p.k??1,0,5,.25,'×10⁻⁵ m⁻¹']},c=configs[l.id];return `<section class="experiment" aria-label="Modo exploración"><div class="scenario-switch"><button class="scenario-btn ${state.params[l.id]?'':'active'}" data-official>Oficial</button><button class="scenario-btn ${state.params[l.id]?'active':''}" data-explore>Exploración</button></div><label>${c[1]} <b id="expVal">${c[2]} ${c[6]}</b></label><input data-param="${c[0]}" type="range" min="${c[3]}" max="${c[4]}" step="${c[5]}" value="${c[2]}" aria-label="${c[1]}"><div class="experiment-result" id="experimentResult">${experimentalResult(l)}</div><button class="reset-inline" data-official>Restablecer datos originales</button></section>`}

function experimentalResult(l){if(!resultVisible(l))return `<span>DATOS MODIFICABLES</span><strong>La incógnita permanece oculta hasta completar el desarrollo.</strong>`;const p=state.params[l.id]||{};if(l.id===1){const L=p.L??1.8;return `<span>ESCENARIO ACTUAL</span><strong>x̄ = ${fmt(L)}/2 = ${fmt(L/2)} m</strong>`}if(l.id===2){const m=p.m3??5,M=5+m,x=(14+2*m)/M,y=(7+5*m)/M;return `<span>ESCENARIO ACTUAL</span><strong>CM = (${fmt(x)}, ${fmt(y)}) m · M=${M} kg</strong>`}if(l.id===3){const h=p.h??3,A=2*h,y2=4+h/3,y=(32+A*y2)/(16+A);return `<span>ESCENARIO ACTUAL</span><strong>ȳ₂=${fmt(y2)} cm · ȳ=${fmt(y)} cm</strong>`}if(l.id===4){const m=p.load??2000,x=(10500+6*m)/(3000+m);return `<span>ESCENARIO ACTUAL</span><strong>x̄=${fmt(x)} m · Δx=${fmt(x-3.5)} m</strong>`}if(l.id===5){const n=p.n??2,M=3*2**(n+1)/(n+1),x=2*(n+1)/(n+2);return `<span>FAMILIA λ(x)=3xⁿ</span><strong>M=${fmt(M)} kg · x̄=${fmt(x)} m</strong>`}const k=(p.k??1)*1e-5,z=-k*200**2/12;return `<span>ESCENARIO ACTUAL</span><strong>zCG=${fmt(z*100)} cm · |Δz|=${fmt(Math.abs(z)*100)} cm</strong>`}
function legend(l){return l.id===6?'<span><i style="background:var(--cyan)"></i>CM</span><span><i style="background:var(--rose)"></i>CG ampliado</span>':'<span><i style="background:var(--cyan)"></i>Centro resultante</span><span><i style="background:var(--gold)"></i>Referencias</span>'}
function visual(l){if(l.id===1)return viz1(l);if(l.id===2)return viz2(l);if(l.id===3)return viz3(l);if(l.id===4)return viz4(l);if(l.id===5)return viz5(l);return viz6(l)}
const svgStart='<svg viewBox="0 0 640 430" role="img" aria-label="Visualización matemática interactiva">';
